    const modelCatalog=document.createElement("div");modelCatalog.className="jt-pro-card";modelCatalog.style.marginTop="13px";modelCatalog.innerHTML='<h3>Provider and agent compatibility</h3><p>These are planned adapters, not authenticated connections. Use provider configuration only for endpoints actually supported by your deployment.</p><div class="jt-pro-list"><div class="jt-pro-item"><div><strong>Ollama / local models</strong><small>Local endpoint test supported by this browser prototype; generation gateway still needs deployment.</small></div><span class="jt-pro-badge">Endpoint test</span></div><div class="jt-pro-item"><div><strong>OpenAI / ChatGPT / Codex</strong><small>Backend adapter and secure credential storage required.</small></div><span class="jt-pro-badge">Adapter needed</span></div><div class="jt-pro-item"><div><strong>Anthropic Claude</strong><small>Backend adapter and secure credential storage required.</small></div><span class="jt-pro-badge">Adapter needed</span></div><div class="jt-pro-item"><div><strong>Google Gemini</strong><small>Backend adapter and secure credential storage required.</small></div><span class="jt-pro-badge">Adapter needed</span></div><div class="jt-pro-item"><div><strong>Codex / OpenCode / Qwen Code / Copilot CLI</strong><small>Native CLI bridge required for local coding-agent execution.</small></div><span class="jt-pro-badge">Native bridge needed</span></div></div>';
