    section.addEventListener("click",async e=>{const a=e.target.closest("[data-pro]")?.dataset.pro;if(a==="save-provider"||a==="save-policy"){const next={provider:document.getElementById("proProvider").value,base:document.getElementById("proBase").value.trim(),model:document.getElementById("proModel").value.trim(),scopes:{read:document.getElementById("scopeRead").checked,write:document.getElementById("scopeWrite").checked,network:document.getElementById("scopeNetwork").checked,desktop:document.getElementById("scopeDesktop").checked}};setStatus(a==="save-provider"?"providerLabStatus":"policyStatus",save(next)?"Saved locally. Server-side policy enforcement is not configured on this static website.":"Browser storage unavailable.",!localStorage);return;}if(a==="test-provider"){const base=document.getElementById("proBase").value.trim().replace(/\/+$/,"");if(!/^https?:\/\//i.test(base)){setStatus("providerLabStatus","Enter a valid http(s) base URL.",true);return;}setStatus("providerLabStatus","Testing public model-list endpoint…");const diag=document.getElementById("providerDiag");diag.innerHTML="";const candidates=document.getElementById("proProvider").value==="Ollama / local"?[base+"/api/tags"]: [base.replace(/\/v1$/,"")+"/v1/models",base+"/models"];let last="Request failed";for(const url of candidates){try{const res=await fetch(url,{method:"GET",signal:AbortSignal.timeout(5000),headers:{Accept:"application/json"}});if(!res.ok){last="HTTP "+res.status+" from "+url;continue;}const data=await res.json();const models=Array.isArray(data.models)?data.models:Array.isArray(data.data)?data.data:[];diag.innerHTML='<div class="jt-pro-item"><div><strong>Endpoint responded</strong><small>'+esc(url)+'</small><small>'+models.length+' model entries returned. No prompt was sent.</small></div><span class="jt-pro-badge">Reachable</span></div>';setStatus("providerLabStatus","Endpoint responded. Browser reachability does not confirm the model can generate responses.");return;}catch(err){last=err.name==="TimeoutError"?"Request timed out":(err.message||"CORS/network error");}}diag.innerHTML='<div class="jt-pro-item"><div><strong>Endpoint not verified</strong><small>'+esc(last)+'</small><small>Local endpoints may require the correct browser CORS/origin configuration.</small></div><span class="jt-pro-badge">Unverified</span></div>';setStatus("providerLabStatus","Could not verify endpoint from this browser. No credentials were sent.",true);}});
